     1	package com.pousada.domain.rateplan;
     2	
     3	import com.pousada.domain.PriceCalculation;
     4	import com.pousada.domain.Room;
     5	import com.pousada.domain.ValidationResult;
     6	import com.pousada.util.DateUtils;
     7	import com.pousada.util.MoneyUtils;
     8	
     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	
    12	public class StandardRatePlan implements RatePlan {
    13	
    14	    @Override
    15	    public ValidationResult validate(LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) {
    16	        return ValidationResult.valid();
    17	    }
    18	
    19	    @Override
    20	    public PriceCalculation calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
    21	        BigDecimal subtotal = calculateSubtotal(room, checkIn, nights);
    22	        BigDecimal discount = MoneyUtils.roundMoney(BigDecimal.ZERO);
    23	        BigDecimal total = subtotal;
    24	
    25	        return new PriceCalculation(subtotal, discount, total);
    26	    }
    27	
    28	    @Override
    29	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    30	        return amountPaid;
    31	    }
    32	
    33	    protected BigDecimal calculateSubtotal(Room room, LocalDate checkIn, int nights) {
    34	        BigDecimal subtotal = BigDecimal.ZERO;
    35	
    36	        for (int i = 0; i < nights; i++) {
    37	            LocalDate night = checkIn.plusDays(i);
    38	            BigDecimal nightRate = room.getNightlyRate();
    39	
    40	            if (DateUtils.isHighSeason(night)) {
    41	                nightRate = MoneyUtils.multiply(nightRate, new BigDecimal("1.20"));
    42	            } else {
    43	                nightRate = MoneyUtils.roundMoney(nightRate);
    44	            }
    45	
    46	            subtotal = subtotal.add(nightRate);
    47	        }
    48	
    49	        return MoneyUtils.roundMoney(subtotal);
    50	    }
    51	}
