     7	import com.pousada.util.DateUtils;
     8	import com.pousada.util.MoneyUtils;
     9	
    10	import java.math.BigDecimal;
    11	import java.time.LocalDate;
    12	import java.util.Map;
    13	
    14	public class WeekendPackageRatePlan implements RatePlan {
    15	
    16	    private static final Map<RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
    17	        RoomType.STANDARD, new BigDecimal("520.00"),
    18	        RoomType.DELUXE, new BigDecimal("820.00"),
    19	        RoomType.SUITE, new BigDecimal("1200.00")
    20	    );
    21	
    22	    @Override
    23	    public ValidationResult validate(LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) {
    24	        if (nights != 2) {
    25	            return ValidationResult.invalid("Weekend package requires exactly 2 nights");
    26	        }
    27	
    28	        if (!DateUtils.isFriday(checkIn)) {
    29	            return ValidationResult.invalid("Weekend package requires Friday check-in");
    30	        }
    31	
    32	        if (!DateUtils.isSunday(checkOut)) {
    33	            return ValidationResult.invalid("Weekend package requires Sunday check-out");
    34	        }
    35	
    36	        return ValidationResult.valid();
    37	    }
    38	
    39	    @Override
    40	    public PriceCalculation calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
    41	        BigDecimal packagePrice = PACKAGE_PRICES.get(room.getType());
    42	        BigDecimal roundedPrice = MoneyUtils.roundMoney(packagePrice);
    43	        BigDecimal discount = MoneyUtils.roundMoney(BigDecimal.ZERO);
    44	
    45	        return new PriceCalculation(roundedPrice, discount, roundedPrice);
    46	    }
    47	
    48	    @Override
    49	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    50	        return MoneyUtils.roundMoney(amountPaid.divide(BigDecimal.valueOf(2)));
    51	    }
    52	}
