    21	        BigDecimal subtotal = calculateSubtotal(room, checkIn, nights);
    22	        BigDecimal discount = MoneyUtils.roundMoney(BigDecimal.ZERO);
    23	        BigDecimal total = subtotal;
    24	
    25	        return new PriceCalculation(subtotal, discount, total);
