    33	    protected BigDecimal calculateSubtotal(Room room, LocalDate checkIn, int nights) {
    34	        BigDecimal subtotal = BigDecimal.ZERO;
    35	
    36	        for (int i = 0; i < nights; i++) {
    37	            LocalDate night = checkIn.plusDays(i);
    38	            BigDecimal nightRate = room.getNightlyRate();
    39	
    40	            if (DateUtils.isHighSeason(night)) {
    41	                nightRate = MoneyUtils.multiply(nightRate, new BigDecimal("1.20"));
    42	            } else {
    43	                nightRate = MoneyUtils.roundMoney(nightRate);
    44	            }
    45	
    46	            subtotal = subtotal.add(nightRate);
    47	        }
    48	
    49	        return MoneyUtils.roundMoney(subtotal);
    50	    }
