     1	package com.pousada.service;
     2	
     3	import com.pousada.domain.Reservation;
     4	import com.pousada.domain.Room;
     5	
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	import java.time.YearMonth;
     9	import java.util.Comparator;
    10	import java.util.List;
    11	import java.util.stream.Collectors;
    12	
    13	public class ReportService {
    14	    private final ReservationService reservationService;
    15	    private final RoomService roomService;
    16	
    17	    public ReportService(ReservationService reservationService, RoomService roomService) {
    18	        this.reservationService = reservationService;
    19	        this.roomService = roomService;
    20	    }
    21	
    22	    public String generateOccupancyReport(LocalDate date) {
    23	        List<Reservation> occupiedReservations = reservationService.getAllReservations().stream()
    24	            .filter(Reservation::isPaid)
    25	            .filter(r -> isOccupiedOnNight(r, date))
    26	            .sorted(Comparator.comparing(Reservation::getRoomNumber))
    27	            .toList();
    28	
    29	        StringBuilder csv = new StringBuilder();
    30	        csv.append("room,type,reservation,check_in,check_out\n");
    31	
    32	        for (Reservation reservation : occupiedReservations) {
    33	            Room room = roomService.findByNumber(reservation.getRoomNumber()).orElseThrow();
    34	            csv.append(reservation.getRoomNumber()).append(",");
    35	            csv.append(room.getType()).append(",");
    36	            csv.append(reservation.getId()).append(",");
    37	            csv.append(reservation.getCheckIn()).append(",");
    38	            csv.append(reservation.getCheckOut()).append("\n");
    39	        }
    40	
    41	        int totalRooms = roomService.getAllRooms().size();
    42	        int occupiedRooms = occupiedReservations.size();
    43	        csv.append("total,").append(occupiedRooms).append("/").append(totalRooms);
    44	
    45	        return csv.toString();
    46	    }
    47	
    48	    public String generateRevenueReport(YearMonth month) {
    49	        List<Reservation> monthReservations = reservationService.getAllReservations().stream()
    50	            .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
    51	            .filter(this::hasRevenue)
    52	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    53	                .thenComparing(Reservation::getId))
    54	            .toList();
    55	
    56	        StringBuilder csv = new StringBuilder();
    57	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    58	
    59	        BigDecimal totalRevenue = BigDecimal.ZERO;
    60	
    61	        for (Reservation reservation : monthReservations) {
    62	            BigDecimal revenue = calculateRevenue(reservation);
    63	            totalRevenue = totalRevenue.add(revenue);
    64	
    65	            csv.append(reservation.getId()).append(",");
    66	            csv.append(reservation.getRoomNumber()).append(",");
    67	            csv.append(reservation.getCheckIn()).append(",");
    68	            csv.append(reservation.getCheckOut()).append(",");
    69	            csv.append(reservation.getStatus()).append(",");
    70	            csv.append(formatCsvMoney(revenue)).append("\n");
    71	        }
    72	
    73	        csv.append("total,").append(formatCsvMoney(totalRevenue));
    74	
    75	        return csv.toString();
    76	    }
    77	
    78	    private boolean isOccupiedOnNight(Reservation reservation, LocalDate night) {
    79	        return !night.isBefore(reservation.getCheckIn()) && night.isBefore(reservation.getCheckOut());
    80	    }
    81	
    82	    private boolean hasRevenue(Reservation reservation) {
    83	        BigDecimal revenue = calculateRevenue(reservation);
    84	        return revenue.compareTo(BigDecimal.ZERO) > 0;
    85	    }
    86	
    87	    private BigDecimal calculateRevenue(Reservation reservation) {
    88	        BigDecimal paid = reservation.getAmountPaid();
    89	        BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
    90	        return paid.subtract(refunded);
    91	    }
    92	
    93	    private String formatCsvMoney(BigDecimal amount) {
    94	        return amount.toString();
    95	    }
    96	}
