    38	        if (guests > room.getCapacity()) {
    39	            throw new CapacityExceededException("Room capacity exceeded");
    40	        }
    41	
    42	        RatePlan ratePlan = RatePlanFactory.create(ratePlanType);
    43	
    44	        ValidationResult validation = ratePlan.validate(checkIn, checkOut, nights, companyCode);
    45	        if (!validation.isValid()) {
    46	            throw new InvalidRequestException(validation.getErrorMessage());
    47	        }
    48	
    49	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
    50	            throw new RoomUnavailableException("Room not available for selected dates");
    51	        }
    52	
    53	        PriceCalculation price;
    54	        if (ratePlanType == RatePlanType.CORPORATE && ratePlan instanceof CorporateRatePlan corporatePlan) {
    55	            price = corporatePlan.calculatePriceWithCompany(room, checkIn, nights, companyCode);
    56	        } else {
    57	            price = ratePlan.calculatePrice(room, checkIn, checkOut, nights);
    58	        }
