    39	            throw new CapacityExceededException("Room capacity exceeded");
    40	        }
    41	
    42	        RatePlan ratePlan = RatePlanFactory.create(ratePlanType);
    43	
    44	        ValidationResult validation = ratePlan.validate(checkIn, checkOut, nights, companyCode);
    45	        if (!validation.isValid()) {
    46	            throw new InvalidRequestException(validation.getErrorMessage());
    47	        }
    48	
    49	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
    50	            throw new RoomUnavailableException("Room not available for selected dates");
    51	        }
    52	
    53	        PriceCalculation price;
    54	        if (ratePlanType == RatePlanType.CORPORATE && ratePlan instanceof CorporateRatePlan corporatePlan) {
    55	            price = corporatePlan.calculatePriceWithCompany(room, checkIn, nights, companyCode);
    56	        } else {
    57	            price = ratePlan.calculatePrice(room, checkIn, checkOut, nights);
    58	        }
    59	
    60	        Long id = idGenerator.getAndIncrement();
    61	        Reservation reservation = new Reservation(
    62	            id, roomNumber, guestName, guestEmail, guestCpf,
    63	            checkIn, checkOut, guests, ratePlanType, companyCode,
    64	            nights, price.getSubtotal(), price.getDiscount(), price.getTotal()
    65	        );
    66	
    67	        reservations.put(id, reservation);
    68	        return reservation;
    69	    }
    70	
    71	    public Reservation confirmReservation(Long id) {
    72	        Reservation reservation = getReservation(id);
    73	        reservation.confirm();
    74	
    75	        String receipt = ReceiptFormatter.formatReceipt(reservation, getRoomType(reservation.getRoomNumber()));
    76	        String emailBody = ReceiptFormatter.formatConfirmationEmail(reservation, getRoomType(reservation.getRoomNumber()));
    77	
    78	        messageService.send(
    79	            MessageChannel.EMAIL,
    80	            reservation.getGuestEmail(),
    81	            "Reserva confirmada - Pousada Maré Alta",
    82	            emailBody
    83	        );
    84	
    85	        return reservation;
    86	    }
    87	
    88	    public Reservation cancelReservation(Long id) {
    89	        Reservation reservation = getReservation(id);
    90	
    91	        RatePlan ratePlan = RatePlanFactory.create(reservation.getRatePlanType());
    92	        BigDecimal refund = ratePlan.calculateRefund(reservation.getAmountPaid());
    93	
    94	        reservation.cancel(refund);
    95	        return reservation;
    96	    }
    97	
    98	    public Reservation checkIn(Long id) {
    99	        Reservation reservation = getReservation(id);
   100	        reservation.checkIn();
   101	        return reservation;
   102	    }
   103	
   104	    public Reservation checkOut(Long id) {
   105	        Reservation reservation = getReservation(id);
   106	        reservation.checkOut();
