   122	    private boolean isRoomUnavailable(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
   123	        return reservations.values().stream()
   124	            .filter(Reservation::isActive)
   125	            .filter(r -> r.getRoomNumber().equals(roomNumber))
   126	            .anyMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
   127	    }
