     8	
     9	    public static long calculateNights(LocalDate checkIn, LocalDate checkOut) {
    10	        return ChronoUnit.DAYS.between(checkIn, checkOut);
    11	    }
    12	
    13	    public static boolean isHighSeason(LocalDate date) {
    14	        int year = date.getYear();
    15	
    16	        LocalDate highSeasonStart = LocalDate.of(year, Month.DECEMBER, 15);
    17	        LocalDate highSeasonEnd = LocalDate.of(year + 1, Month.FEBRUARY, 28);
    18	        if (LocalDate.of(year + 1, 1, 1).isLeapYear()) {
    19	            highSeasonEnd = LocalDate.of(year + 1, Month.FEBRUARY, 29);
    20	        }
    21	
    22	        LocalDate julyStart = LocalDate.of(year, Month.JULY, 1);
    23	        LocalDate julyEnd = LocalDate.of(year, Month.JULY, 31);
    24	
    25	        return (date.isAfter(highSeasonStart.minusDays(1)) && date.isBefore(highSeasonEnd.plusDays(1))) ||
    26	               (date.isAfter(julyStart.minusDays(1)) && date.isBefore(julyEnd.plusDays(1)));
    27	    }
    28	
    29	    public static boolean isFriday(LocalDate date) {
    30	        return date.getDayOfWeek().getValue() == 5;
    31	    }
    32	
    33	    public static boolean isSunday(LocalDate date) {
    34	        return date.getDayOfWeek().getValue() == 7;
    35	    }
    36	}
