    12	public class ReceiptFormatter {
    13	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    14	    private static final NumberFormat MONEY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
    15	
    16	    public static String formatReceipt(Reservation reservation, RoomType roomType) {
    17	        StringBuilder receipt = new StringBuilder();
    18	
    19	        receipt.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    20	        receipt.append("Hóspede: ").append(reservation.getGuestName())
    21	               .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    22	        receipt.append("Quarto: ").append(reservation.getRoomNumber())
    23	               .append(" (").append(roomType).append(")\n");
    24	        receipt.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
    25	               .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
    26	               .append(" | ").append(formatNights(reservation.getNights())).append("\n");
    27	        receipt.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
    28	
    29	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    30	            receipt.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
    31	        }
    32	
    33	        receipt.append("Total: ").append(formatMoney(reservation.getTotal()));
    34	
    35	        return receipt.toString();
    36	    }
    37	
    38	    public static String formatConfirmationEmail(Reservation reservation, RoomType roomType) {
    39	        String receipt = formatReceipt(reservation, roomType);
    40	
    41	        return String.format("""
    42	            Olá, %s!
    43	
    44	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
    45	
    46	            %s
    47	
    48	            A entrada é a partir das 14h, e a saída, até as 12h.
    49	            Até breve!""", reservation.getGuestName(), receipt);
    50	    }
    51	
    52	    private static String formatCpf(String cpf) {
    53	        if (cpf.length() == 11) {
    54	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    55	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
    56	        }
    57	        return cpf;
    58	    }
    59	
    60	    private static String formatDate(LocalDate date) {
    61	        return date.format(DATE_FORMAT);
    62	    }
    63	
    64	    private static String formatMoney(BigDecimal amount) {
    65	        return MONEY_FORMAT.format(amount);
    66	    }
    67	
    68	    private static String formatNights(int nights) {
    69	        return nights == 1 ? "1 diária" : nights + " diárias";
    70	    }
    71	}

